/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['biocontainers/scanpy','biocontainers/anndata']:
    url=f'https://quay.io/api/v1/repository/{repo}/tag/?limit=20'
    try:
        data=json.load(urllib.request.urlopen(url, timeout=20))
        print(repo)
        for t in data.get('tags', [])[:20]:
            print(t.get('name'), t.get('manifest_digest') or t.get('manifest_digest'))
    except Exception as e:
        print(repo, 'ERR', e)
PY"

